    // @dev called after a hlvWithdrawal cancellation
    // @param key the key of the hlvWithdrawal
    // @param hlvWithdrawal the hlvWithdrawal that was cancelled
    function afterHlvWithdrawalCancellation(
        bytes32 key,
        HlvWithdrawal.Props memory hlvWithdrawal,
